// 1. The Procedural Way (data is separate, passed into functions):
public class ProceduralDemo {
    public static void displayStudent(String name, int age, String course) {
        System.out.println(name + " is " + age + " years old and learning " + course);
    }
}

// 2. The Object-Oriented Way (data and behavior live together):
class Student {
    String name;
    int age;
    String course;

    void display() {
        // The student already knows its own name, age, and course!
        System.out.println(name + " is " + age + " years old and learning " + course);
    }
}

public class Main {
    public static void main(String[] args) {
        Student s = new Student();
        s.name = "Priya";
        s.age = 21;
        s.course = "Python";
        s.display(); // Notice: No need to pass name, age, course! The student knows.
    }
}

