class BankAccount {
    String accountHolder;
    double balance;

    void showBalance() {
        System.out.println("Account Holder: " + accountHolder + " | Balance: $" + balance);
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount acc = new BankAccount();
        acc.accountHolder = "Vikram";
        acc.balance = 1500.0;
        acc.showBalance();
    }
}

class Car {
    String model;
    int topSpeed;

    void displaySpecs() {
        System.out.println("Model: " + model + ", Top Speed: " + topSpeed + " km/h");
    }
}

public class Main {
    public static void main(String[] args) {
        Car c = new Car();
        c.model = "Tesla Model 3";
        c.topSpeed = 225;
        c.displaySpecs();
    }
}

class Order {
    String itemName;
    int quantity;
    double unitPrice;

    void printInvoice() {
        double total = quantity * unitPrice;
        System.out.println("Order: " + quantity + " x " + itemName + " = $" + total);
    }
}

public class Main {
    public static void main(String[] args) {
        Order o = new Order();
        o.itemName = "Wireless Earbuds";
        o.quantity = 3;
        o.unitPrice = 49.99;
        o.printInvoice();
    }
}

class CoffeeMachine {
    String waterStatus;
    int coffeeBeans;

    void brew() {
        System.out.println("Brewing espresso with " + coffeeBeans + "g beans (Water: " + waterStatus + ")");
    }
}

public class Main {
    public static void main(String[] args) {
        CoffeeMachine cm = new CoffeeMachine();
        cm.waterStatus = "Full";
        cm.coffeeBeans = 18;
        cm.brew();
    }
}

class EmployeeSalary {
    String employeeName;
    double basicSalary;

    void printTaxDeduction() {
        double tax = basicSalary * 0.10;
        System.out.println("Employee: " + employeeName + " | Tax: $" + tax);
    }
}

public class Main {
    public static void main(String[] args) {
        EmployeeSalary emp = new EmployeeSalary();
        emp.employeeName = "Ananya";
        emp.basicSalary = 5000.0;
        emp.printTaxDeduction();
    }
}
